//! TypeScript bindings for `packages/api-types/src/generated`, written by
//! `cargo xtask gen-ts-types` and checked for drift by this crate's tests.

use std::collections::BTreeMap;
use std::io;
use std::path::Path;

use ts_rs::{Config, ExportError, TS};

use crate::auth_dto::*;
use crate::compose_dto::*;
use crate::desktop_dto::*;
use crate::dto::*;
use crate::ops_dto::*;
use crate::push_dto::*;

/// Path of the generated bindings, relative to the workspace root.
pub const OUT_DIR: &str = "packages/api-types/src/generated";

const INDEX_HEADER: &str =
    "// Generated by `cargo xtask gen-ts-types`. Do not edit this file manually.\n";

fn file<T: TS + 'static>(
    cfg: &Config,
    files: &mut BTreeMap<String, String>,
) -> Result<(), ExportError> {
    files.insert(format!("{}.ts", T::name(cfg)), T::export_to_string(cfg)?);
    Ok(())
}

/// Content-Security-Policy values, for test doubles of the server.
const CSP_FILE: &str = "csp.ts";

fn csp() -> String {
    let consts = [
        ("API_CSP", crate::api::API_CSP),
        ("APP_CSP", crate::api::APP_CSP),
        ("WEB_APP_CSP", crate::api::WEB_APP_CSP),
        ("RENDER_CSP", crate::messages::RENDER_CSP),
        ("PART_CSP", crate::messages::PART_CSP),
    ];
    std::iter::once(INDEX_HEADER.to_owned())
        .chain(consts.iter().map(|(name, value)| {
            let value = serde_json::to_string(value).expect("strings serialize");
            format!("export const {name} = {value};\n")
        }))
        .collect()
}

